// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Attempt to call assertionDisputedCallback and capture whether it reverts
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.assertionDisputedCallback.selector, assertionId));
        assertTrue(success, "assertionDisputedCallback should not revert");
    }
}

